@Bean
public Logger logger() {
    return LoggerFactory.getLogger("timeout-logger")
            .setLevel(Level.INFO)
            .addHandler(new TimeoutLogger(30));
}

class TimeoutLogger extends Handler {
    private final int timeoutDuration;

    public TimeoutLogger(int timeoutDuration) {
        this.timeoutDuration = timeoutDuration;
    }

    @Override
    public void handle(LogRecord record) {
        if (record.getLevel().isInfo()) {
            try {
                Thread.sleep(timeoutDuration * 1000);
            } catch (InterruptedException e) {
                // ignore
            }
            // log the message after the specified timeout duration
        }
    }
}
```
