    private static final int MAX_REQUESTS = 10; // adjust this value as needed

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        return chain.filter(exchange)
                .then(new RateLimiterFactoryFilter.Builder()
