import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class ThrottlingStrategy {
    private final RedisTemplate<String, Long> redisTemplate;

    public ThrottlingStrategy(RedisTemplate<String, Long> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    public boolean shouldThrottle(Request request) {
        // retrieve the current request count from Redis
        Long requestCount = redisTemplate.opsForValue().get("requestCount");

        if (requestCount == null) {
            // initialize the request count to 0
            redisTemplate.opsForValue().set("requestCount", 1L);
            return false;
        }

        // increment the request count
        requestCount++;

        // check if we've reached the maximum allowed requests
        if (requestCount > MAX_REQUESTS) {
            return true;
        }

        // store the updated request count in Redis
        redisTemplate.opsForValue().set("requestCount", requestCount);

        return false;
    }
}
